import { expect, test } from 'vitest';

test('EvidenceGrid.svelte is generated', () => {
	expect('EvidenceGrid.svelte').toContain('.svelte');
});

import { expect, test } from 'vitest';

test('reports view route is generated', () => {
	expect('src/routes/reports/+page.svelte').toContain('reports');
});

import { expect, test } from 'vitest';

test('reports layout route is generated', () => {
	expect('src/routes/reports/+layout.svelte').toContain('reports');
});

import { json } from '@sveltejs/kit';

export function GET(): Response {
	return json({ ok: true, resource: 'audit-log' });
}

import { expect, test } from 'vitest';
import { GET } from '../../src/routes/api/audit-log/+server';

test('audit-log API returns ok', async () => {
	const response = GET();
	expect(await response.json()).toEqual({ ok: true, resource: 'audit-log' });
});

export function createFilterStateStore(initialValue = '') {
	let value = $state(initialValue);

	return {
		get value(): string {
			return value;
		},
		set value(nextValue: string) {
			value = nextValue;
		}
	};
}

import { expect, test } from 'vitest';
import { createFilterStateStore } from '../../src/lib/stores/filterState.svelte';

test('createFilterStateStore stores values', () => {
	const store = createFilterStateStore('first');
	store.value = 'next';
	expect(store.value).toBe('next');
});

import type { Handle } from '@sveltejs/kit';

export const sessionHook: Handle = async ({ event, resolve }) => {
	return resolve(event);
};

import { expect, test } from 'vitest';
import { sessionHook } from '../../src/hooks/sessionHook.server';

test('sessionHook is a SvelteKit handle', () => {
	expect(sessionHook).toBeTypeOf('function');
});

import { expect, test } from './support/browserTest';

test('evidence-grid page loads', async ({ page }) => {
	await page.goto('/evidence-grid');
	await expect(page.locator('[data-harness-view="evidence-grid"]')).toBeVisible();
});

